insert into zt.pages(id,module,family,sig,spec,txt) values ('D01','pin','DA',$j${"r":2,"b":1}$j$::jsonb,$j${"red":{"t":"even"},"blue":{"t":"ge","k":6},"src":"piles","clues":[{"w":["piles",2],"c":[{"t":"sum","v":10},{"t":"max","v":6}]},{"w":["piles",3],"c":[{"t":"min","v":2},{"t":"sum","v":20}]},{"w":["piles",4],"c":[{"t":"sum","v":18},{"t":"min","v":1}]}]}$j$::jsonb,$j${"sig":"Voyants allumés — 2 rouges et 1 bleu","rules":["<strong>Voyants rouges (ronds)</strong> : un voyant par chiffre pair du code (le 0 est pair).","<strong>Voyants bleus (carrés)</strong> : un voyant par chiffre du code supérieur ou égal à 6.","<strong>2 piles</strong> : la somme des quatre chiffres vaut 10 ; le plus grand chiffre est 6.","<strong>3 piles</strong> : le plus petit chiffre est 2 ; la somme des quatre chiffres vaut 20.","<strong>4 piles</strong> : la somme des quatre chiffres vaut 18 ; le plus petit chiffre est 1."],"end":"Annoncez les quatre chiffres à l’opérateur, un par un, dans cet ordre.","note":"Comptez d’abord les piles de la bombe. Les quatre chiffres du code sont tous différents ; un code refusé compte comme une erreur.","stamp":"VÉRIFIER LES PILES"}$j$::jsonb);
insert into zt.pages(id,module,family,sig,spec,txt) values ('D02','pin','DA',$j${"r":2,"b":2}$j$::jsonb,$j${"red":{"t":"even"},"blue":{"t":"ge","k":6},"src":"piles","clues":[{"w":["piles",2],"c":[{"t":"has","v":7},{"t":"sum","v":14}]},{"w":["piles",3],"c":[{"t":"max","v":8},{"t":"sum","v":16}]},{"w":["piles",4],"c":[{"t":"sum","v":24},{"t":"min","v":2}]}]}$j$::jsonb,$j${"sig":"Voyants allumés — 2 rouges et 2 bleus","rules":["<strong>Voyants rouges (ronds)</strong> : un voyant par chiffre pair du code (le 0 est pair).","<strong>Voyants bleus (carrés)</strong> : un voyant par chiffre du code supérieur ou égal à 6.","<strong>2 piles</strong> : le code contient le chiffre 7 ; la somme des quatre chiffres vaut 14.","<strong>3 piles</strong> : le plus grand chiffre est 8 ; la somme des quatre chiffres vaut 16.","<strong>4 piles</strong> : la somme des quatre chiffres vaut 24 ; le plus petit chiffre est 2."],"end":"Annoncez les quatre chiffres à l’opérateur, un par un, dans cet ordre.","note":"Comptez d’abord les piles de la bombe. Les quatre chiffres du code sont tous différents ; un code refusé compte comme une erreur.","stamp":null}$j$::jsonb);
insert into zt.pages(id,module,family,sig,spec,txt) values ('D03','pin','DA',$j${"r":1,"b":2}$j$::jsonb,$j${"red":{"t":"even"},"blue":{"t":"ge","k":6},"src":"piles","clues":[{"w":["piles",2],"c":[{"t":"sum","v":19},{"t":"has","v":5}]},{"w":["piles",3],"c":[{"t":"min","v":1},{"t":"sum","v":23}]},{"w":["piles",4],"c":[{"t":"sum","v":17},{"t":"has","v":3}]}]}$j$::jsonb,$j${"sig":"Voyants allumés — 1 rouge et 2 bleus","rules":["<strong>Voyants rouges (ronds)</strong> : un voyant par chiffre pair du code (le 0 est pair).","<strong>Voyants bleus (carrés)</strong> : un voyant par chiffre du code supérieur ou égal à 6.","<strong>2 piles</strong> : la somme des quatre chiffres vaut 19 ; le code contient le chiffre 5.","<strong>3 piles</strong> : le plus petit chiffre est 1 ; la somme des quatre chiffres vaut 23.","<strong>4 piles</strong> : la somme des quatre chiffres vaut 17 ; le code contient le chiffre 3."],"end":"Annoncez les quatre chiffres à l’opérateur, un par un, dans cet ordre.","note":"Comptez d’abord les piles de la bombe. Les quatre chiffres du code sont tous différents ; un code refusé compte comme une erreur.","stamp":null}$j$::jsonb);
insert into zt.pages(id,module,family,sig,spec,txt) values ('D04','pin','DB',$j${"r":3,"b":1}$j$::jsonb,$j${"red":{"t":"odd"},"blue":{"t":"le","k":3},"src":"serie","clues":[{"w":["somme_paire",true],"c":[{"t":"min","v":2}]},{"w":["somme_paire",false],"c":[{"t":"sum","v":27}]},{"w":["voyelle",true],"c":[{"t":"has","v":9}]},{"w":["voyelle",false],"c":[{"t":"max","v":9}]}]}$j$::jsonb,$j${"sig":"Voyants allumés — 3 rouges et 1 bleu","rules":["<strong>Voyants rouges (ronds)</strong> : un voyant par chiffre impair du code.","<strong>Voyants bleus (carrés)</strong> : un voyant par chiffre du code inférieur ou égal à 3.","Si la somme des deux chiffres du numéro de série est <strong>paire</strong> : le plus petit chiffre est 2.","Si cette somme est <strong>impaire</strong> : la somme des quatre chiffres vaut 27.","Si le numéro de série contient <strong>une voyelle</strong> (A, E, U ou Y) : le code contient le chiffre 9.","Si le numéro de série ne contient <strong>aucune voyelle</strong> : le plus grand chiffre est 9."],"end":"Annoncez les quatre chiffres à l’opérateur, un par un, dans cet ordre.","note":"Appliquez un indice sur la somme et un indice sur les voyelles. Les quatre chiffres du code sont tous différents ; un code refusé compte comme une erreur.","stamp":"ATTENTION AUX ERREURS"}$j$::jsonb);
insert into zt.pages(id,module,family,sig,spec,txt) values ('D05','pin','DB',$j${"r":3,"b":2}$j$::jsonb,$j${"red":{"t":"odd"},"blue":{"t":"le","k":3},"src":"serie","clues":[{"w":["somme_paire",true],"c":[{"t":"not","v":7}]},{"w":["somme_paire",false],"c":[{"t":"not","v":5}]},{"w":["voyelle",true],"c":[{"t":"min","v":2}]},{"w":["voyelle",false],"c":[{"t":"max","v":8}]}]}$j$::jsonb,$j${"sig":"Voyants allumés — 3 rouges et 2 bleus","rules":["<strong>Voyants rouges (ronds)</strong> : un voyant par chiffre impair du code.","<strong>Voyants bleus (carrés)</strong> : un voyant par chiffre du code inférieur ou égal à 3.","Si la somme des deux chiffres du numéro de série est <strong>paire</strong> : le code ne contient pas le chiffre 7.","Si cette somme est <strong>impaire</strong> : le code ne contient pas le chiffre 5.","Si le numéro de série contient <strong>une voyelle</strong> (A, E, U ou Y) : le plus petit chiffre est 2.","Si le numéro de série ne contient <strong>aucune voyelle</strong> : le plus grand chiffre est 8."],"end":"Annoncez les quatre chiffres à l’opérateur, un par un, dans cet ordre.","note":"Appliquez un indice sur la somme et un indice sur les voyelles. Les quatre chiffres du code sont tous différents ; un code refusé compte comme une erreur.","stamp":null}$j$::jsonb);
insert into zt.pages(id,module,family,sig,spec,txt) values ('D06','pin','DB',$j${"r":1,"b":3}$j$::jsonb,$j${"red":{"t":"odd"},"blue":{"t":"le","k":3},"src":"serie","clues":[{"w":["somme_paire",true],"c":[{"t":"sum","v":13}]},{"w":["somme_paire",false],"c":[{"t":"sum","v":7}]},{"w":["voyelle",true],"c":[{"t":"not","v":7}]},{"w":["voyelle",false],"c":[{"t":"min","v":0}]}]}$j$::jsonb,$j${"sig":"Voyants allumés — 1 rouge et 3 bleus","rules":["<strong>Voyants rouges (ronds)</strong> : un voyant par chiffre impair du code.","<strong>Voyants bleus (carrés)</strong> : un voyant par chiffre du code inférieur ou égal à 3.","Si la somme des deux chiffres du numéro de série est <strong>paire</strong> : la somme des quatre chiffres vaut 13.","Si cette somme est <strong>impaire</strong> : la somme des quatre chiffres vaut 7.","Si le numéro de série contient <strong>une voyelle</strong> (A, E, U ou Y) : le code ne contient pas le chiffre 7.","Si le numéro de série ne contient <strong>aucune voyelle</strong> : le plus petit chiffre est 0."],"end":"Annoncez les quatre chiffres à l’opérateur, un par un, dans cet ordre.","note":"Appliquez un indice sur la somme et un indice sur les voyelles. Les quatre chiffres du code sont tous différents ; un code refusé compte comme une erreur.","stamp":null}$j$::jsonb);
